/**
 * Compile-time static Protobuf types from proto/chat_realtime.proto.
 *
 * Uses pbjs/pbts static code generation instead of runtime .proto parsing.
 * Generated by scripts/generate-proto.sh — regenerate with: npm run generate-proto
 */

import { chat } from "./chat_realtime_pb.js";

const v1 = chat.realtime.v1;

/* ── Enum constants ───────────────────────────────────────────────── */

export const RealtimeEventType = {
  UNSPECIFIED: v1.RealtimeEventType.REALTIME_EVENT_TYPE_UNSPECIFIED as 0,
  MESSAGE_CREATED: v1.RealtimeEventType.MESSAGE_CREATED as 1,
  CONVERSATION_CREATED: v1.RealtimeEventType.CONVERSATION_CREATED as 2,
  CONVERSATION_UPDATED: v1.RealtimeEventType.CONVERSATION_UPDATED as 3,
  TYPING_UPDATED: v1.RealtimeEventType.TYPING_UPDATED as 4,
} as const;
export type RealtimeEventTypeValue = (typeof RealtimeEventType)[keyof typeof RealtimeEventType];

export const ConversationType = {
  UNSPECIFIED: v1.ConversationType.CONVERSATION_TYPE_UNSPECIFIED as 0,
  GROUP: v1.ConversationType.GROUP as 1,
  DIRECT: v1.ConversationType.DIRECT as 2,
} as const;
export type ConversationTypeValue = (typeof ConversationType)[keyof typeof ConversationType];

export const MessageType = {
  UNSPECIFIED: v1.MessageType.MESSAGE_TYPE_UNSPECIFIED as 0,
  TEXT: v1.MessageType.TEXT as 1,
} as const;
export type MessageTypeValue = (typeof MessageType)[keyof typeof MessageType];

/* ── TypeScript interfaces (camelCase, matching GraphQL DTOs) ────── */

export interface User {
  id: string;
  username: string;
  name: string;
  avatarUrl?: string;
  title?: string;
}

export interface MessagePreview {
  id: string;
  conversationId: string;
  sender: User;
  body: string;
  type: MessageTypeValue;
  createdAt: string;
}

export interface MessageQuote {
  id: string;
  sender: User;
  body: string;
  type: MessageTypeValue;
  createdAt: string;
}

export interface Message {
  id: string;
  conversationId: string;
  sender: User;
  type: MessageTypeValue;
  body: string;
  quoteMessage?: MessageQuote;
  mentions: User[];
  createdAt: string;
  updatedAt: string;
}

export interface Conversation {
  id: string;
  name: string;
  type: ConversationTypeValue;
  avatarUrls: string[];
  memberCount: number;
  unreadCount: number;
  mentionCount: number;
  lastMessage?: MessagePreview;
  createdAt: string;
  updatedAt: string;
}

export interface MessageCreatedPayload {
  message: Message;
}

export interface ConversationCreatedPayload {
  conversation: Conversation;
}

export interface ConversationUpdatedPayload {
  conversation: Conversation;
}

export interface TypingUpdatedPayload {
  conversationId: string;
  user: User;
  isTyping: boolean;
}

export type RealtimeEventPayload =
  | { type: typeof RealtimeEventType.MESSAGE_CREATED; messageCreated: MessageCreatedPayload }
  | { type: typeof RealtimeEventType.CONVERSATION_CREATED; conversationCreated: ConversationCreatedPayload }
  | { type: typeof RealtimeEventType.CONVERSATION_UPDATED; conversationUpdated: ConversationUpdatedPayload }
  | { type: typeof RealtimeEventType.TYPING_UPDATED; typingUpdated: TypingUpdatedPayload };

export interface RealtimeEvent {
  eventId: string;
  type: RealtimeEventTypeValue;
  emittedAt: string;
  payload: RealtimeEventPayload | null;
}

/* ── Payload type map (type value → camelCase field name) ────────── */

const PAYLOAD_MAP: Record<
  number,
  { camelField: string }
> = {
  [RealtimeEventType.MESSAGE_CREATED]: {
    camelField: "messageCreated",
  },
  [RealtimeEventType.CONVERSATION_CREATED]: {
    camelField: "conversationCreated",
  },
  [RealtimeEventType.CONVERSATION_UPDATED]: {
    camelField: "conversationUpdated",
  },
  [RealtimeEventType.TYPING_UPDATED]: {
    camelField: "typingUpdated",
  },
};

/* ── Encode / Decode ──────────────────────────────────────────────── */

let eventCounter = 0;

export function encodeRealtimeEvent(
  type: RealtimeEventTypeValue,
  payload: object,
): Uint8Array {
  const entry = PAYLOAD_MAP[type];
  if (!entry) {
    throw new Error(`Unknown RealtimeEventType value: ${type}`);
  }

  const eventObj = {
    eventId: `evt_${Date.now()}_${++eventCounter}`,
    type,
    emittedAt: new Date().toISOString(),
    [entry.camelField]: payload,
  };

  const errMsg = v1.RealtimeEvent.verify(eventObj);
  if (errMsg) {
    throw new Error(`RealtimeEvent verify failed: ${errMsg}`);
  }

  return v1.RealtimeEvent.encode(eventObj).finish();
}

export function decodeRealtimeEvent(data: Uint8Array): RealtimeEvent {
  const decoded = v1.RealtimeEvent.decode(data);
  const obj = v1.RealtimeEvent.toObject(decoded, {
    longs: String,
    enums: Number,
    defaults: true,
    oneofs: true,
  }) as Record<string, unknown>;

  const type = obj.type as number;
  const entry = PAYLOAD_MAP[type];

  let payload: RealtimeEventPayload | null = null;
  if (entry && obj[entry.camelField]) {
    const rawPayload = obj[entry.camelField] as Record<string, unknown>;

    switch (type) {
      case RealtimeEventType.MESSAGE_CREATED:
        payload = { type, messageCreated: rawPayload as unknown as MessageCreatedPayload };
        break;
      case RealtimeEventType.CONVERSATION_CREATED:
        payload = { type, conversationCreated: rawPayload as unknown as ConversationCreatedPayload };
        break;
      case RealtimeEventType.CONVERSATION_UPDATED:
        payload = { type, conversationUpdated: rawPayload as unknown as ConversationUpdatedPayload };
        break;
      case RealtimeEventType.TYPING_UPDATED:
        payload = { type, typingUpdated: rawPayload as unknown as TypingUpdatedPayload };
        break;
    }
  }

  return {
    eventId: obj.eventId as string,
    type: type as RealtimeEventTypeValue,
    emittedAt: obj.emittedAt as string,
    payload,
  };
}
